    ui.bind(el, maxS,  reclamp)
    ui.bind(el, stepS, function ()  { if (!editing) txt.value = fmt(sig.peek()) })
    ui.bind(el, precS, function ()  { if (!editing) txt.value = fmt(sig.peek()) })

